import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract tenant context
function tenantContext(req, res, next) {
  req.tenantId = req.headers['x-tenant-id'] || 'default';
  req.userRole = req.headers['x-user-role'] || 'viewer';
  next();
}

app.use(tenantContext);

// Search endpoint with dynamic filtering
app.get('/api/v2/reports/search', async (req, res) => {
  try {
    const { category, date_from, date_to, sort_field, sort_dir } = req.query;

    // Base query with tenant isolation
    let query = `SELECT id, title, category, created_at, summary 
                 FROM reports WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (date_from) {
      query += ` AND created_at >= $${paramIdx}`;
      params.push(date_from);
      paramIdx++;
    }

    if (date_to) {
      query += ` AND created_at <= $${paramIdx}`;
      params.push(date_to);
      paramIdx++;
    }

    // Sort handling - validated against allowlist... mostly
    const allowedSorts = ['created_at', 'title', 'category', 'id'];
    const direction = sort_dir === 'desc' ? 'DESC' : 'ASC';

    if (sort_field) {
      if (allowedSorts.includes(sort_field)) {
        query += ` ORDER BY ${sort_field} ${direction}`;
      } else {
        // Fallback: use the field with quoting for "custom" columns
        query += ` ORDER BY "${sort_field}" ${direction}`;
      }
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    query += ` LIMIT 50`;

    const result = await pool.query(query, params);
    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/reports/export', async (req, res) => {
  try {
    const { report_ids, format } = req.body;

    if (!Array.isArray(report_ids) || report_ids.length === 0) {
      return res.status(400).json({ error: 'report_ids required' });
    }

    if (report_ids.length > 100) {
      return res.status(400).json({ error: 'Max 100 reports per export' });
    }

    const placeholders = report_ids.map((_, i) => `$${i + 2}`).join(',');
    const query = `SELECT * FROM reports WHERE tenant_id = $1 AND id IN (${placeholders})`;
    const result = await pool.query(query, [req.tenantId, ...report_ids]);

    const exportId = crypto.randomUUID();
    res.json({ export_id: exportId, records: result.rowCount });
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Admin analytics - role check
app.get('/api/v2/admin/analytics', async (req, res) => {
  if (req.userRole !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const { metric_name } = req.query;
  // Direct interpolation for pg_stat views - these are system views
  const query = `SELECT * FROM pg_stat_user_tables WHERE relname = '${metric_name}'`;

  try {
    const result = await pool.query(query);
    res.json({ metrics: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Query failed' });
  }
});

app.listen(3000, () => console.log('Report service running on :3000'));
